        def generate_sequences(rem_target, rem_m, max_d, current):
            if rem_m == 1:
                if 0 <= rem_target <= max_d:
                    seq = current + [rem_target]
                    is_g = True
                    sum_d = 0
                    for k in range(1, m + 1):
                        sum_d += seq[k-1]
                        rhs = k * (k - 1)
                        for i in range(k, m):
                            rhs += min(k, seq[i])
                        if sum_d > rhs:
                            is_g = False
                            break
                    if is_g:
                        yield seq
                return

            for d in range(min(rem_target, max_d), -1, -1):
                if rem_target - d <= (rem_m - 1) * d:
                    yield from generate_sequences(rem_target - d, rem_m - 1, d, current + [d])

        for seq in generate_sequences(2 * n, m, m - 1, []):
            val = get_max_sum(seq)
            if val > max_val:
                max_val = val
        results.append((n, max_val))
        print(f"n={n}, max_cost={max_val}")
    return results

